actions.script:
            // ZE-SALES-014 f/u: org-isolate the CSV/XLSX export (standalone render skips the authz filter)
            def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
            def _txnFind = ec.entity.find("zenith.erp.pos.PosTransaction")
                .condition("statusId", "PtCompleted")
                .condition("entryDate", "greater-equals", dayStart)
                .condition("entryDate", "less-equals", dayEnd)
            if (_org) _txnFind.condition("organizationPartyId", _org)
            def txns = _txnFind.list()

            def txnIds = txns.collect { it.transactionId }
            itemWiseList = []
            totalQty = BigDecimal.ZERO
            totalAmount = BigDecimal.ZERO

            if (txnIds) {
                def items = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                    .condition("transactionId", "in", txnIds).list()

                def productMap = new LinkedHashMap()
                items.each { item ->
                    def key = item.productId ?: item.productName ?: 'Unknown'
                    if (!productMap[key]) {
                        productMap[key] = [productId: item.productId ?: '', productName: item.productName ?: item.productId ?: 'Unknown',
                            totalQty: BigDecimal.ZERO, totalAmount: BigDecimal.ZERO, avgPrice: BigDecimal.ZERO, txnCount: 0 as int]
                    }
                    productMap[key].totalQty += (item.quantity ?: 0) as BigDecimal
                    productMap[key].totalAmount += (item.lineTotal ?: 0) as BigDecimal
                    productMap[key].txnCount++
                }
                productMap.values().each { p ->
                    if (p.totalQty > 0) p.avgPrice = (p.totalAmount / p.totalQty).setScale(2, java.math.RoundingMode.HALF_UP)
                }
                itemWiseList = productMap.values().sort { -(it.totalAmount as BigDecimal) }
                totalQty = itemWiseList.sum { it.totalQty } ?: BigDecimal.ZERO
                totalAmount = itemWiseList.sum { it.totalAmount } ?: BigDecimal.ZERO
            }
